from pathlib import Path
p=Path('index.html')
s=p.read_text()

def rep(a,b):
    global s
    if a not in s:
        raise SystemExit('missing target: '+a[:140])
    s=s.replace(a,b,1)

rep('LAME — Howie Lucas Pinball v32','LAME — Howie Lucas Pinball v33')
rep('drainCommitted=false,autoPlay=false,computerLaunchAt=0,computerFlipAt=0;', 'drainCommitted=false,autoPlay=false,computerLaunchAt=0,computerFlipAt=0,computerLastDecision=null,computerLastHitAt=0;')

old='function draw(){ctx.clearRect(0,0,W,VIEW_H);ctx.save();ctx.translate(0,-cameraY);drawWorld();ctx.restore()}function computerTap(side){const now=performance.now();if(side==="L"){left=true;flipperMotionUntil.L=now+190;setTimeout(()=>{if(autoPlay)left=false},125)}else{right=true;flipperMotionUntil.R=now+190;setTimeout(()=>{if(autoPlay)right=false},125)}}function computerControl(){if(!autoPlay||!playing||transitioning||won)return;const now=performance.now();if(waiting){if(computerLaunchAt&&now>=computerLaunchAt){computerLaunchAt=0;const p=.78+Math.random()*.22;setLaunchPower(p);launch(p);setStatus("🤖 COMPUTER LAUNCHED THE BALL")}return}if(inShooter||drainCommitted)return;if(ball.vy>0&&ball.y>900&&ball.y<1145&&now>=computerFlipAt){const predicted=ball.x+ball.vx*5.5;if(predicted<345)computerTap("L");if(predicted>255)computerTap("R");computerFlipAt=now+155;setStatus("🤖 COMPUTER IS PLAYING • LEVEL "+level+"/5")}}function loop(){computerControl();physics();draw();if(boxOpen===4&&playing)outEl.textContent=fmt(outMs());requestAnimationFrame(loop)}'
new='function draw(){ctx.clearRect(0,0,W,VIEW_H);ctx.save();ctx.translate(0,-cameraY);drawWorld();ctx.restore()}const COMPUTER_BRAIN_KEY="lameComputerBrainV33";let computerBrain=(()=>{try{return Object.assign({lead:8.5,centerBias:0,leftOffset:0,rightOffset:0,misses:0,saves:0,recent:[]},JSON.parse(localStorage.getItem(COMPUTER_BRAIN_KEY)||"{}"))}catch(e){return{lead:8.5,centerBias:0,leftOffset:0,rightOffset:0,misses:0,saves:0,recent:[]}}})();function saveComputerBrain(){try{localStorage.setItem(COMPUTER_BRAIN_KEY,JSON.stringify(computerBrain))}catch(e){}}function computerTap(side){const now=performance.now();computerLastDecision={side,x:ball.x,y:ball.y,vx:ball.vx,vy:ball.vy,at:now};if(side==="L"){left=true;flipperMotionUntil.L=now+215;setTimeout(()=>{if(autoPlay)left=false},145)}else{right=true;flipperMotionUntil.R=now+215;setTimeout(()=>{if(autoPlay)right=false},145)}}function learnComputerFromDrain(){if(!autoPlay)return;computerBrain.misses++;const d=computerLastDecision||{side:null,x:ball.x,vx:ball.vx};const zone=ball.x<260?"L":ball.x>340?"R":"C";computerBrain.recent.push({zone,side:d.side,vx:Math.round(d.vx||0)});computerBrain.recent=computerBrain.recent.slice(-8);computerBrain.lead=Math.min(13,computerBrain.lead+.45);if(zone==="L")computerBrain.leftOffset=Math.max(-45,computerBrain.leftOffset-6);else if(zone==="R")computerBrain.rightOffset=Math.min(45,computerBrain.rightOffset+6);else computerBrain.centerBias+=(d.side==="L"?7:d.side==="R"?-7:(ball.vx>=0?-5:5));const same=computerBrain.recent.slice(-3);if(same.length===3&&same.every(r=>r.zone===zone&&r.side===d.side)){computerBrain.lead=Math.min(14,computerBrain.lead+.8);computerBrain.centerBias+=zone==="L"?-8:zone==="R"?8:(d.side==="L"?10:-10)}saveComputerBrain();setStatus("🤖 COMPUTER LEARNED FROM THAT DRAIN • ADJUSTING TIMING") }function computerPredictX(){if(ball.vy<=.05)return ball.x;const targetY=1068,frames=Math.max(0,Math.min(22,(targetY-ball.y)/Math.max(.4,ball.vy*.88)));let x=ball.x+ball.vx*frames*.88;while(x<24||x>576){if(x<24)x=48-x;if(x>576)x=1152-x}return x}function computerControl(){if(!autoPlay||!playing||transitioning||won)return;const now=performance.now();if(waiting){if(computerLaunchAt&&now>=computerLaunchAt){computerLaunchAt=0;const p=.86+Math.random()*.12;setLaunchPower(p);launch(p);setStatus("🤖 COMPUTER LAUNCHED THE BALL") }return}if(inShooter||drainCommitted)return;if(ball.vy>0&&ball.y>760&&ball.y<1140&&now>=computerFlipAt){let predicted=computerPredictX()+computerBrain.centerBias;const urgency=Math.max(0,Math.min(1,(ball.y-820)/270));const triggerY=955-Math.min(95,(computerBrain.lead-8.5)*18);if(ball.y<triggerY&&urgency<.6)return;let side;if(predicted<285+computerBrain.leftOffset)side="L";else if(predicted>315+computerBrain.rightOffset)side="R";else side=ball.vx<=0?"L":"R";const recent=computerBrain.recent.slice(-2);if(recent.length===2&&recent.every(r=>r.zone==="C"&&r.side===side))side=side==="L"?"R":"L";computerTap(side);computerFlipAt=now+Math.max(95,155-computerBrain.misses*2);setStatus("🤖 COMPUTER PREDICTS "+side+" FLIP • LEARNING MODE")}}function loop(){computerControl();physics();draw();if(boxOpen===4&&playing)outEl.textContent=fmt(outMs());requestAnimationFrame(loop)}'
rep(old,new)

