new2='if(moving){sfxFlipper();const dot=ball.vx*nx+ball.vy*ny;if(dot<0){ball.vx-=2.15*dot*nx;ball.vy-=2.15*dot*ny}const upwardKick=10.2+4.8*t;ball.vy=Math.min(ball.vy,-6)-upwardKick;ball.vx+=(side==="L"?1:-1)*(1.7+2.8*t);ball.y-=3;if(autoPlay&&performance.now()-computerLastHitAt>220){computerLastHitAt=performance.now();computerBrain.saves++;computerBrain.lead=Math.max(7.2,computerBrain.lead-.05);if(side==="L")computerBrain.leftOffset=Math.min(20,computerBrain.leftOffset+1);else computerBrain.rightOffset=Math.max(-20,computerBrain.rightOffset-1);saveComputerBrain()}}else{'
